#!/usr/bin/env python3
"""Generate crates/ink-ui/src/theme/tokens.rs from replica/design/tokens.json.

Usage: python3 -I replica/design/tools/gen_theme.py [--check]
--check exits 1 if the generated file is out of date (for CI).
Components must use these tokens, never raw colors or numbers.
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
SRC = ROOT / "replica/design/tokens.json"
OUT = ROOT / "crates/ink-ui/src/theme/tokens.rs"


def ident(name):
    return name.replace("-", "_")


def color(hex_):
    h = hex_.lstrip("#")
    r, g, b = (int(h[i:i + 2], 16) for i in (0, 2, 4))
    if len(h) == 8:
        a = int(h[6:8], 16)
        pm = lambda v: (v * a + 127) // 255
        return f"Color32::from_rgba_premultiplied({pm(r)}, {pm(g)}, {pm(b)}, {a})"
    return f"Color32::from_rgb({r}, {g}, {b})"


def gen(t):
    out = [
        "// @generated by replica/design/tools/gen_theme.py from replica/design/tokens.json.",
        "// Do not edit by hand: change tokens.json and re-run the generator.",
        "#![allow(dead_code)]",
        "",
        "use egui::Color32;",
        "",
    ]
    roles = list(t["color"]["dark"].keys())
    for theme in t["color"].values():
        assert list(theme.keys()) == roles or set(theme.keys()) == set(roles), "themes must define the same roles"
    out.append("/// Color roles. Every theme defines every role.")
    out.append("#[derive(Clone, Copy, Debug, PartialEq)]")
    out.append("pub struct Palette {")
    for r in roles:
        out.append(f"    pub {ident(r)}: Color32,")
    out.append("}")
    out.append("")
    for name, theme in t["color"].items():
        out.append(f"pub const {name.upper()}: Palette = Palette {{")
        for r in roles:
            out.append(f"    {ident(r)}: {color(theme[r])},")
        out.append("};")
        out.append("")

    out.append("/// Font sizes and line heights in points.")
    out.append("pub mod font {")
    for k, v in t["font"]["size"].items():
        out.append(f"    pub const {ident(k).upper()}: f32 = {float(v['size'])};")
        out.append(f"    pub const {ident(k).upper()}_LINE: f32 = {float(v['line'])};")
    out.append("}")
    out.append("")

    def scalar_mod(name, d, doc):
        out.append(f"/// {doc}")
        out.append(f"pub mod {name} {{")
        for k, v in d.items():
            key = ident(k).upper()
            if key[0].isdigit():
                key = "S" + key
            out.append(f"    pub const {key}: f32 = {float(v)};")
        out.append("}")
        out.append("")

    scalar_mod("space", t["space"], "Spacing scale (4px base, 2px half-step).")
    scalar_mod("radius", t["radius"], "Corner radii.")
    scalar_mod("stroke", t["stroke"], "Stroke widths.")
    scalar_mod("control_h", t["control"]["height"], "Control heights.")
    scalar_mod("icon", t["control"]["icon"], "Icon sizes.")
    scalar_mod("pad_x", t["control"]["padding-x"], "Horizontal control padding.")

    out.append("/// Motion durations in seconds. Zero them when the OS asks for reduced motion.")
    out.append("pub mod motion {")
    out.append(f"    pub const FAST: f32 = {t['motion']['fast-ms'] / 1000};")
    out.append(f"    pub const BASE: f32 = {t['motion']['base-ms'] / 1000};")
    out.append("}")
    out.append("")

    out.append("/// Shadows: (offset_x, offset_y, blur, spread, color).")
    out.append("pub mod shadow {")
    out.append("    use egui::Color32;")
    for k, v in t["shadow"].items():
        out.append(f"    pub const {ident(k).upper()}: (i8, i8, u8, u8, Color32) = ({v['x']}, {v['y']}, {v['blur']}, {v['spread']}, {color(v['color'])});")
    out.append("}")
    out.append("")

    out.append("/// Layout sizes.")
    out.append("pub mod layout {")
    for k, v in t["layout"].items():
        key = ident(k).upper()
        if isinstance(v, dict):
            for kk, vv in v.items():
                out.append(f"    pub const {key}_{ident(kk).upper()}: f32 = {float(vv)};")
        else:
            out.append(f"    pub const {key}: f32 = {float(v)};")
    out.append("}")
    out.append("")
    return "\n".join(out)


def main():
    text = gen(json.loads(SRC.read_text()))
    if "--check" in sys.argv:
        if not OUT.exists() or OUT.read_text() != text:
            print(f"{OUT} is out of date; run gen_theme.py", file=sys.stderr)
            sys.exit(1)
        return
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(text)
    print(f"wrote {OUT.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
